// === Tab: SandSpread ===

let originalImg;
let edgeImg;
let input;

// For the liquid metal simulation
let particles = [];
let flowField; // A 2D array of vectors to guide particles
let imageReady = false;
let isProcessing = false;
let lightSource;

// To handle image scaling and positioning
let imgX, imgY, imgW, imgH;

function setup() {
  createCanvas(windowWidth, windowHeight);
  pixelDensity(1);

  input = createFileInput(handleFile);
  input.position(20, 20);

  // A simulated light source for the 3D effect (from top-left)
  lightSource = createVector(-1, -1);
  lightSource.normalize();

  drawInstructions("Upload an image to begin.");
}

function draw() {
  background(10, 15, 20);

  if (isProcessing) {
    // This state is handled by drawInstructions
  } else if (imageReady) {
    // Calculate display dimensions once
    let ratio = min((width * 0.9) / edgeImg.width, (height * 0.9) / edgeImg.height);
    imgW = edgeImg.width * ratio;
    imgH = edgeImg.height * ratio;
    imgX = (width - imgW) / 2;
    imgY = (height - imgH) / 2;

    // You can uncomment the next line to see the underlying edge map
    // tint(255, 50);
    // image(edgeImg, imgX, imgY, imgW, imgH);
    // noTint();

    // Update and display all particles
    for (let i = particles.length - 1; i >= 0; i--) {
      particles[i].update();
      particles[i].display();
    }
  } else {
    // This state is handled by drawInstructions
  }
}

function handleFile(file) {
  if (file.type === 'image') {
    isProcessing = true;
    imageReady = false;
    particles = [];
    drawInstructions("Loading image...");
    originalImg = loadImage(file.data, () => {
      drawInstructions("Processing edges...");
      // Use setTimeout to allow browser to render the message
      setTimeout(processImage, 50);
    });
  } else {
    originalImg = null;
    edgeImg = null;
    imageReady = false;
    drawInstructions("File is not an image. Please try again.");
  }
}

function processImage() {
  // --- Step 1: Edge Detection (Sobel Operator) ---
  if (originalImg.width > 600) {
      originalImg.resize(600, 0);
  }
  edgeImg = createImage(originalImg.width, originalImg.height);
  originalImg.loadPixels();
  edgeImg.loadPixels();

  const Gx = [[-1, 0, 1], [-2, 0, 2], [-1, 0, 1]];
  const Gy = [[-1, -2, -1], [0, 0, 0], [1, 2, 1]];

  for (let y = 1; y < originalImg.height - 1; y++) {
    for (let x = 1; x < originalImg.width - 1; x++) {
      let sumX = 0, sumY = 0;
      for (let ky = -1; ky <= 1; ky++) {
        for (let kx = -1; kx <= 1; kx++) {
          let idx = ((y + ky) * originalImg.width + (x + kx)) * 4;
          let brightness = (originalImg.pixels[idx] + originalImg.pixels[idx + 1] + originalImg.pixels[idx + 2]) / 3;
          sumX += brightness * Gx[ky + 1][kx + 1];
          sumY += brightness * Gy[ky + 1][kx + 1];
        }
      }
      let magnitude = sqrt(sumX * sumX + sumY * sumY);
      let edgeIndex = (y * edgeImg.width + x) * 4;
      edgeImg.pixels[edgeIndex] = magnitude;
      edgeImg.pixels[edgeIndex + 1] = magnitude;
      edgeImg.pixels[edgeIndex + 2] = magnitude;
      edgeImg.pixels[edgeIndex + 3] = 255;
    }
  }
  edgeImg.updatePixels();

  // --- Step 2: Create the Flow Field ---
  drawInstructions("Calculating flow field...");
  setTimeout(calculateFlowField, 50);
}

function calculateFlowField() {
  flowField = Array(edgeImg.width).fill(null).map(() => Array(edgeImg.height).fill(null));
  edgeImg.loadPixels();

  for (let y = 1; y < edgeImg.height - 1; y++) {
    for (let x = 1; x < edgeImg.width - 1; x++) {
      let bestNeighbor = createVector(x, y);
      let maxBrightness = -1;

      // Find the brightest neighbor to flow towards
      for (let ky = -1; ky <= 1; ky++) {
        for (let kx = -1; kx <= 1; kx++) {
          if (kx === 0 && ky === 0) continue;
          let nx = x + kx;
          let ny = y + ky;
          let index = (ny * edgeImg.width + nx) * 4;
          var brightness = edgeImg.pixels[index];
          if (brightness > maxBrightness) {
            maxBrightness = brightness;
            bestNeighbor.set(nx, ny);
          }
        }
      }
      let currentBrightness = edgeImg.pixels[(y * edgeImg.width + x) * 4];
      if (maxBrightness > currentBrightness) {
        let direction = p5.Vector.sub(bestNeighbor, createVector(x, y));
        flowField[x][y] = direction.normalize();
      } else {
        // If this pixel is a local maximum, it's a "peak," so flow is zero.
        flowField[x][y] = createVector(0, 0);
      }
    }
  }

  isProcessing = false;
  imageReady = true;
  drawInstructions("Ready. Click to pour liquid metal.");
}

function mousePressed() {
  if (imageReady) {
    // Convert screen coordinates to image coordinates
    let mx = ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - imgX) * (edgeImg.width / imgW);
    let my = ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - imgY) * (edgeImg.height / imgH);

    // Create a burst of particles
    let numParticles = 500;
    for (let i = 0; i < numParticles; i++) {
      particles.push(new Particle(mx, my));
    }
  }
}

function drawInstructions(message) {
  background(10, 15, 20);
  fill(220);
  noStroke();
  textAlign(CENTER, CENTER);
  textSize(24);
  text(message, width / 2, height / 2);
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  if (!imageReady && !isProcessing) {
    drawInstructions("Upload an image to begin.");
  } else if (imageReady) {
    drawInstructions("Ready. Click to pour liquid metal.");
  }
}


// --- Particle Class ---
class Particle {
  constructor(x, y) {
    // Start at the specified image coordinate
    this.imgPos = createVector(x, y);
    this.vel = p5.Vector.random2D().mult(random(2, 4));
    this.acc = createVector(0, 0);
    this.maxSpeed = 3;
    this.isSettled = false;
    this.settledColor = color(0);
  }

  update() {
    if (this.isSettled) return;

    // Check bounds
    if (this.imgPos.x < 1 || this.imgPos.x > edgeImg.width - 2 || this.imgPos.y < 1 || this.imgPos.y > edgeImg.height - 2) {
      this.isSettled = true; // Settle particles that go out of bounds
      return;
    }

    // Get the flow direction from the pre-calculated field
    let ix = floor(this.imgPos.x);
    let iy = floor(this.imgPos.y);
    let force = flowField[ix][iy];
    if (force) {
        this.acc.add(force);
    }

    this.vel.add(this.acc);
    this.vel.limit(this.maxSpeed);
    this.imgPos.add(this.vel);
    this.acc.mult(0); // Reset acceleration

    // Dampen velocity to help particles settle
    this.vel.mult(0.95);

    // Check if the particle should settle
    let edgeStrength = edgeImg.get(ix, iy)[0];
    if (edgeStrength > 50 && this.vel.mag() < 0.5) {
      this.isSettled = true;

      // Calculate final color once for performance
      // The normal is perpendicular to the flow vector (gradient)
      let gradient = flowField[ix][iy] || createVector(0,0);
      let normal = createVector(-gradient.y, gradient.x);

      // Lambertian reflection model for shading
      let lighting = p5.Vector.dot(normal, lightSource);
      let shade = map(lighting, -1, 1, 60, 255);
      this.settledColor = color(shade);
    }
  }

  display() {
    // Convert image position to screen position for drawing
    let screenX = this.imgPos.x * (imgW / edgeImg.width) + imgX;
    let screenY = this.imgPos.y * (imgH / edgeImg.height) + imgY;

    if (this.isSettled) {
      fill(this.settledColor);
    } else {
      // Unsettled particles are bright white
      fill(255, 255, 255, 200);
    }

    noStroke();
    rect(screenX, screenY, 2, 2);
  }
}

